$ErrorActionPreference = 'Stop'
function Patch-File($path, $pairs) {
  if (-not (Test-Path $path)) { Write-Host "MISSING: $path" -ForegroundColor Red; return $false }
  $c = [IO.File]::ReadAllText($path) -replace "`r`n","`n"
  $applied = 0
  foreach ($p in $pairs) {
    $old = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($p[0]))
    $new = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($p[1]))
    if ($c.Contains($new) -and -not $c.Contains($old)) { $applied++; continue }  # already patched
    if (-not $c.Contains($old)) { Write-Host "HUNK NOT FOUND in $path (no changes written)" -ForegroundColor Red; return $false }
    $c = $c.Replace($old, $new); $applied++
  }
  $utf8 = New-Object System.Text.UTF8Encoding($false)  # no BOM; LF preserved
  [IO.File]::WriteAllText($path, $c, $utf8)
  Write-Host "PATCHED $path ($applied hunks)" -ForegroundColor Green
  return $true
}

